    // FenrirOS: bindgen's library panics here ("Not an item: ItemId(43962)" in Type::layout) on LLVM 23 / libc++ headers, while the
    // bindgen command-line tool (the same 0.73.2 code, `bindgen` package) generates these bindings from the same headers with the same
    // options. So the bindings are generated by the command-line tool, with the options the code below passes to the library (taken
    // from Builder::command_line_flags() in a debug build), and the library code that follows is not reached.
    {
        let mut cmd = std::process::Command::new("bindgen");
        cmd.arg(add_include("ProfilerBindings.h"))
            .arg("-o")
            .arg(OUTDIR_PATH.join(BINDINGS_FILE))
            .args(["--opaque-type", "std::string"])
            .args(["--opaque-type", "std::unique_ptr"])
            .args(["--opaque-type", "mozilla::Maybe"])
            .args(["--opaque-type", "mozilla::MallocAllocPolicy"])
            .args(["--opaque-type", "mozilla::Variant"])
            .args(["--opaque-type", "mozilla::baseprofiler::UniqueJSONStrings"])
            .args(["--opaque-type", "std::vector.*"])
            .args(["--allowlist-type", "mozilla::profiler::detail::RacyFeatures"])
            .args(["--allowlist-function", "gecko_profiler_.*"])
            .args(["--allowlist-var", "mozilla::profiler::detail::RacyFeatures::sActiveAndFeatures"])
            .args(["--allowlist-item", "ThreadProfilingFeatures"])
            .args(["--rustified-enum", "ThreadProfilingFeatures"])
            .args(["--rustified-enum", "mozilla::StackCaptureOptions"])
            .args(["--rustified-enum", "mozilla::MarkerSchema_Location"])
            .args(["--rustified-enum", "mozilla::MarkerSchema_Format"])
            .args(["--rustified-enum", "mozilla::MarkerSchema_PayloadFlags"])
            .arg("--enable-cxx-namespaces")
            .arg("--no-derive-default")
            .args(["--raw-line", "pub use self::root::*;"])
            .args(["--generate", "functions,types,vars"])
            .arg("--ignore-methods")
            .arg("--disable-untagged-union")
            .arg("--");
        for dir in SEARCH_PATHS.iter() {
            cmd.arg("-I").arg(dir);
        }
        cmd.arg("-include").arg(add_include("mozilla-config.h"));
        for item in &*BINDGEN_FLAGS {
            cmd.arg(item);
        }
        cmd.arg("-include").arg(add_include("GeckoProfiler.h"));
        let status = cmd.status().expect("could not run the bindgen command");
        assert!(status.success(), "bindgen failed: {}", status);
        return;
    }
